        }
        int nCurTime = (int) (System.currentTimeMillis() / 1000);
        int nLast = utility.Instance().getIntPreferencesValue(ctx, "startup", 0);
        if (nLast != 0) {
            return Math.abs(nLast - nCurTime) > sdelaytime;
        }
        utility.Instance().SaveIntPreference(ctx, "startup", nCurTime);
        return false;
    }

