            StringBuilder sb = new StringBuilder();
            try {
                BufferedReader reader = new BufferedReader(new InputStreamReader(is, "UTF-8"));
                while (true) {
                    String line = reader.readLine();
                    if (line != null) {
                        sb.append(line).append("\n");
                    } else {
                        is.close();
                        return sb.toString();
                    }
                }
            } catch (Throwable th) {
                is.close();
                throw th;
            }
        } else {
            return "";
        }
    }

