    public void copyFiles() {
        try {
            String roms_dir = this.mm.getPrefsHelper().getROMsDIR();
            if (!new File(String.valueOf(roms_dir) + File.separator + "saves/ok").exists()) {
                File fm = new File(String.valueOf(roms_dir) + File.separator + "saves/" + MAGIC_FILE);
                if (!fm.exists()) {
                    fm.createNewFile();
                    InputStream fis = this.mm.getAssets().open("data");
                    ZipInputStream zis = new ZipInputStream(new BufferedInputStream(fis));
                    byte[] data = new byte[BUFFER_SIZE];
                    while (true) {
                        ZipEntry entry = zis.getNextEntry();
                        if (entry != null) {
                            if (!entry.isDirectory()) {
                                String destFN = String.valueOf(roms_dir) + File.separator + entry.getName();
                                FileOutputStream fos = new FileOutputStream(destFN);
                                BufferedOutputStream dest = new BufferedOutputStream(fos, BUFFER_SIZE);
                                while (true) {
                                    int count = zis.read(data, 0, BUFFER_SIZE);
                                    if (count == -1) {
                                        break;
                                    } else {
                                        dest.write(data, 0, count);
                                    }
                                }
                                dest.flush();
                                dest.close();
                            } else {
                                File f = new File(String.valueOf(roms_dir) + File.separator + entry.getName());
                                f.mkdirs();
                            }
                        } else {
                            zis.close();
                            config.MkDir(String.valueOf(roms_dir) + File.separator + "saves" + File.separator + "ok");
                            return;
                        }
                    }
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

package com.seleuco.mame4all.helpers;

    public static void copyFilesFromApk(String dir, String strGame, String strFilename, Activity ctx, boolean bIsforce) {
        String strName;
        config.MkDir(dir);
        config.MkDir(String.valueOf(dir) + File.separator + "save");
        File fm = new File(String.valueOf(dir) + File.separator + strGame + File.separator + "saves" + File.separator + "ok");
        if (!fm.exists() || bIsforce) {
            String destTemp = String.valueOf(dir) + File.separator + "tmp.zip";
            try {
                File fm2 = new File(String.valueOf(dir) + File.separator + "saves/" + MAGIC_FILE);
                try {
                    if (!fm2.exists() || bIsforce) {
                        File fin = new File(strFilename);
                        InputStream fis = new FileInputStream(fin);
                        File ftem = new File(destTemp);
                        if (ftem != null && (ftem.isFile() || ftem.isDirectory())) {
                            ftem.delete();
                        }
                        ZipInputStream zis = new ZipInputStream(new BufferedInputStream(fis));
                        byte[] data = new byte[BUFFER_SIZE];
                        while (true) {
                            ZipEntry entry = zis.getNextEntry();
                            if (entry != null) {
                                if (!entry.isDirectory() && (strName = entry.getName()) != null && (strName.equals("assets/data") || strName.equals("assets\\data") || strName.equals("assets/roms.zip") || strName.equals("res/raw/roms.zip"))) {
                                    utility.Log("", "copyFilesFromApk " + strName);
                                    FileOutputStream fos = new FileOutputStream(destTemp);
                                    BufferedOutputStream dest = new BufferedOutputStream(fos, BUFFER_SIZE);
                                    while (true) {
                                        int count = zis.read(data, 0, BUFFER_SIZE);
                                        if (count == -1) {
                                            break;
                                        } else {
                                            dest.write(data, 0, count);
                                        }
                                    }
                                    dest.flush();
                                    dest.close();
                                    copyFilesFromzip(String.valueOf(dir) + File.separator + strGame, destTemp, ctx, bIsforce);
                                }
                            } else {
                                zis.close();
                                return;
                            }
                        }
                    }
                } catch (Exception e) {
                    e = e;
                    e.printStackTrace();
                }
            } catch (Exception e2) {
                e = e2;
            }
        }
    }

