    public boolean ensureROMsDir(String roms_dir) {
        File res_dir = new File(roms_dir);
        boolean created = false;
        if (!res_dir.exists()) {
            if (!res_dir.mkdirs()) {
                this.mm.getDialogHelper().setErrorMsg("Can't find/create:\n '" + roms_dir + "'\nIs it writeable?");
                this.mm.showDialog(2);
                return false;
            }
            created = true;
        }
        String str_sav_dir = String.valueOf(roms_dir) + "saves/";
        File sav_dir = new File(str_sav_dir);
        if (!sav_dir.exists() && !sav_dir.mkdirs()) {
            this.mm.getDialogHelper().setErrorMsg("Can't find/create:\n'" + str_sav_dir + "'\nIs it writeable");
            this.mm.showDialog(2);
            return false;
        }
        if (created) {
            this.mm.getDialogHelper().setInfoMsg("Created: \n'" + roms_dir + "'\nCopy or move your zipped ROMs under './MAME4All/roms' directory!.\n\nMAME4droid uses only 'gp2x wiz 0.37b11 MAME romset'. Google it or use clrmame.dat file included  to convert romsets from other MAME versions. See  help.");
            this.mm.showDialog(3);
        }
        return true;
    }

