    public int getscrOrientation() {
        Display getOrient = this.mm.getWindowManager().getDefaultDisplay();
        int orientation = this.mm.getResources().getConfiguration().orientation;
        if (orientation == 0) {
            Configuration config = this.mm.getResources().getConfiguration();
            int orientation2 = config.orientation;
            if (orientation2 == 0) {
                if (getOrient.getWidth() == getOrient.getHeight()) {
                    return 3;
                }
                if (getOrient.getWidth() < getOrient.getHeight()) {
                    return 1;
                }
                return 2;
            }
            return orientation2;
        }
        return orientation;
    }

