    public static boolean isRomsReady(String dir, String strGame, Activity ctx) {
        File fm = new File(String.valueOf(dir) + File.separator + strGame + File.separator + "saves" + File.separator + "ok");
        if (fm.exists()) {
            File file = new File(String.valueOf(File.separator) + strGame + File.separator + "roms");
            if (file == null || !file.isDirectory()) {
                return true;
            }
            String[] names = file.list();
            for (int i = 0; i < names.length; i++) {
                if (names[i] != null && names[i].contains(".zip")) {
                    return true;
                }
            }
            return true;
        }
        return false;
    }

