    public ArrayList<Integer> measureWindow(int widthMeasureSpec, int heightMeasureSpec, int scaleType) {
        int widthSize;
        int heightSize;
        int newHeight;
        if (scaleType == 6) {
            widthSize = View.MeasureSpec.getSize(widthMeasureSpec);
            heightSize = View.MeasureSpec.getSize(heightMeasureSpec);
        } else {
            int emu_w = Emulator.getEmulatedWidth();
            int emu_h = Emulator.getEmulatedHeight();
            if (scaleType == 2) {
                emu_w = (int) (emu_w * 1.5f);
                emu_h = (int) (emu_h * 1.5f);
            }
            if (scaleType == 3) {
                emu_w *= 2;
                emu_h *= 2;
            }
            if (scaleType == 4) {
                emu_w = (int) (emu_w * 2.5f);
                emu_h = (int) (emu_h * 2.5f);
            }
            int w = emu_w;
            int h = emu_h;
            int widthSize2 = View.MeasureSpec.getSize(widthMeasureSpec);
            int heightSize2 = View.MeasureSpec.getSize(heightMeasureSpec);
            if (heightSize2 == 0) {
                heightSize2 = 1;
            }
            if (widthSize2 == 0) {
                widthSize2 = 1;
            }
            float scale = 1.0f;
            if (scaleType == 5) {
                scale = Math.min(widthSize2 / w, heightSize2 / h);
            }
            float desiredAspect = emu_w / emu_h;
            widthSize = Math.min((int) (w * scale), widthSize2);
            heightSize = Math.min((int) (h * scale), heightSize2);
            float actualAspect = widthSize / heightSize;
            if (Math.abs(actualAspect - desiredAspect) > 1.0E-7d) {
                boolean done = false;
                int newWidth = (int) (heightSize * desiredAspect);
                if (newWidth <= widthSize) {
                    widthSize = newWidth;
                    done = true;
                }
                if (!done && (newHeight = (int) (widthSize / desiredAspect)) <= heightSize) {
                    heightSize = newHeight;
                }
            }
        }
        ArrayList<Integer> l = new ArrayList<>();
        l.add(new Integer(widthSize));
        l.add(new Integer(heightSize));
        return l;
    }
}

