    protected int updateAnalog(int pad_data) {
        switch (this.mm.getPrefsHelper().getAnalogDZ()) {
            case 0:
                this.deadZone = 0.01f;
                break;
            case 1:
                this.deadZone = 0.05f;
                break;
            case 2:
                this.deadZone = 0.1f;
                break;
            case 3:
                this.deadZone = 0.15f;
                break;
            case 4:
                this.deadZone = 0.2f;
                break;
            case 5:
                this.deadZone = 0.3f;
                break;
        }
        if (this.mag >= this.deadZone) {
            int ways = Emulator.getValue(6);
            boolean b = Emulator.isInMAME();
            Emulator.setAnalogData(0, this.rx, this.ry * (-1.0f));
            float v = this.ang;
            if (ways == 2 && b) {
                if (v < 180.0f) {
                    return (pad_data | 64) & (-2) & (-17) & (-5);
                }
                if (v >= 180.0f) {
                    return (pad_data | 4) & (-2) & (-17) & (-65);
                }
                return pad_data;
            }
            if (ways == 4 && b) {
                if (v >= 315.0f || v < 45.0f) {
                    return (pad_data | 16) & (-2) & (-5) & (-65);
                }
                if (v >= 45.0f && v < 135.0f) {
                    return (pad_data | 64) & (-2) & (-17) & (-5);
                }
                if (v >= 135.0f && v < 225.0f) {
                    return (pad_data | 1) & (-17) & (-5) & (-65);
                }
                if (v >= 225.0f && v < 315.0f) {
                    return (pad_data | 4) & (-2) & (-17) & (-65);
                }
                return pad_data;
            }
            if (v >= 330.0f || v < 30.0f) {
                return (pad_data | 16) & (-2) & (-5) & (-65);
            }
            if (v >= 30.0f && v < 60.0f) {
                return (pad_data | 16 | 64) & (-2) & (-5);
            }
            if (v >= 60.0f && v < 120.0f) {
                return (pad_data | 64) & (-2) & (-17) & (-5);
            }
            if (v >= 120.0f && v < 150.0f) {
                return (pad_data | 64 | 1) & (-17) & (-5);
            }
            if (v >= 150.0f && v < 210.0f) {
                return (pad_data | 1) & (-17) & (-5) & (-65);
            }
            if (v >= 210.0f && v < 240.0f) {
                return (pad_data | 1 | 4) & (-17) & (-65);
            }
            if (v >= 240.0f && v < 300.0f) {
                return (pad_data | 4) & (-2) & (-17) & (-65);
            }
            if (v >= 300.0f && v < 330.0f) {
                return (pad_data | 4 | 16) & (-2) & (-65);
            }
            return pad_data;
        }
        Emulator.setAnalogData(0, 0.0f, 0.0f);
        return pad_data & (-2) & (-17) & (-5) & (-65);
    }

    protected void calculateStickState(Point pt, Point min, Point max, Point center) {
        if (pt.x > max.x) {
            pt.x = max.x;
        }
        if (pt.x < min.x) {
            pt.x = min.x;
        }
        if (pt.y > max.y) {
            pt.y = max.y;
        }
        if (pt.y < min.y) {
            pt.y = min.y;
        }
        if (pt.x == center.x) {
            this.rx = 0.0f;
        } else if (pt.x >= center.x) {
            this.rx = (pt.x - center.x) / (max.x - center.x);
        } else {
            this.rx = ((pt.x - min.x) / (center.x - min.x)) - 1.0f;
        }
        if (pt.y == center.y) {
            this.ry = 0.0f;
        } else if (pt.y >= center.y) {
            this.ry = (pt.y - center.y) / (max.y - center.y);
        } else {
            this.ry = ((pt.y - min.y) / (center.y - min.y)) - 1.0f;
        }
        this.ang = rad2degree((float) Math.atan(this.ry / this.rx));
        this.ang -= 90.0f;
        if (this.rx < 0.0f) {
            this.ang -= 180.0f;
        }
        this.ang = Math.abs(this.ang);
        this.mag = (float) Math.sqrt((this.rx * this.rx) + (this.ry * this.ry));
    }

    protected void calculateStickPosition(Point pt) {
        int ways = Emulator.getValue(6);
        boolean b = Emulator.isInMAME();
        if (ways == 2 && b) {
            this.stickPos.left = Math.min(this.ptMax.x - this.stickWidth, Math.max(this.ptMin.x, pt.x - (this.stickWidth / 2)));
            this.stickPos.top = this.ptCenter.y - (this.stickHeight / 2);
        } else if (ways == 4 && b) {
            if (this.mm.getInputHandler().getStick_state() == 5 || this.mm.getInputHandler().getStick_state() == 4) {
                this.stickPos.left = Math.min(this.ptMax.x - this.stickWidth, Math.max(this.ptMin.x, pt.x - (this.stickWidth / 2)));
                this.stickPos.top = this.ptCenter.y - (this.stickHeight / 2);
            } else {
                this.stickPos.left = this.ptCenter.x - (this.stickWidth / 2);
                this.stickPos.top = Math.min(this.ptMax.y - this.stickHeight, Math.max(this.ptMin.y, pt.y - (this.stickHeight / 2)));
            }
        } else {
            this.stickPos.left = Math.min(this.ptMax.x - this.stickWidth, Math.max(this.ptMin.x, pt.x - (this.stickWidth / 2)));
            this.stickPos.top = Math.min(this.ptMax.y - this.stickHeight, Math.max(this.ptMin.y, pt.y - (this.stickHeight / 2)));
        }
        this.stickPos.right = this.stickPos.left + this.stickWidth;
        this.stickPos.bottom = this.stickPos.top + this.stickHeight;
    }

    public int handleMotion(MotionEvent event, int pad_data) {
        int pid;
        int action = event.getAction();
        int actionEvent = action & 255;
        int pointerIndex = (65280 & action) >> 8;
        try {
            pid = event.getPointerId(pointerIndex);
        } catch (Error e) {
            pid = (action & 8) >> 8;
        }
        if (actionEvent == 1 || ((actionEvent == 6 && pid == this.motion_pid) || actionEvent == 3)) {
            this.ptCur.x = this.ptCenter.x;
            this.ptCur.y = this.ptCenter.y;
            this.mag = 0.0f;
            this.ry = 0.0f;
            this.rx = 0.0f;
            this.oldRy = -999.0f;
            this.oldRx = -999.0f;
            this.motion_pid = -1;
        } else {
            for (int i = 0; i < event.getPointerCount(); i++) {
                int pointerId = event.getPointerId(i);
                int x = (int) event.getX(i);
                int y = (int) event.getY(i);
                if (this.rStickArea.contains(x, y)) {
                    this.motion_pid = pointerId;
                }
                if (this.motion_pid == pointerId) {
                    this.ptCur.x = x;
                    this.ptCur.y = y;
                    calculateStickState(this.ptCur, this.ptMin, this.ptMax, this.ptCenter);
                }
            }
        }
        int pad_data2 = updateAnalog(pad_data);
        if ((Math.abs(this.oldRx - this.rx) >= 0.08d || Math.abs(this.oldRy - this.ry) >= 0.08d) && this.mm.getPrefsHelper().isAnimatedInput()) {
            this.oldRx = this.rx;
            this.oldRy = this.ry;
            calculateStickPosition(this.mag >= this.deadZone ? this.ptCur : this.ptCenter);
            if (this.mm.getPrefsHelper().getControllerType() == 3) {
                if (Emulator.isDebug()) {
                    this.mm.getInputView().invalidate();
                } else {
                    this.mm.getInputView().invalidate(this.rStickArea);
                }
            }
        }
        return pad_data2;
    }

    public void draw(Canvas canvas) {
        if (this.mm.getPrefsHelper().getControllerType() == 3) {
            if (this.mm.getMainHelper().getscrOrientation() == 2) {
                outer_img.setBounds(this.rStickArea);
                outer_img.setAlpha(this.mm.getInputHandler().getOpacity());
                outer_img.draw(canvas);
            }
            inner_img.setBounds(this.stickPos);
            inner_img.setAlpha(this.mm.getInputHandler().getOpacity());
            inner_img.draw(canvas);
        } else if (this.mm.getPrefsHelper().getControllerType() == 2) {
            stick_images[this.mm.getInputHandler().getStick_state()].setBounds(this.rStickArea);
            stick_images[this.mm.getInputHandler().getStick_state()].setAlpha(this.mm.getInputHandler().getOpacity());
            stick_images[this.mm.getInputHandler().getStick_state()].draw(canvas);
        }
        if (Emulator.isDebug()) {
            canvas.drawText("x=" + this.ptCur.x + " y=" + this.ptCur.y + " state=" + this.mm.getInputHandler().getStick_state() + " rx=" + this.rx + " ry=" + this.ry + " ang=" + this.ang + " mag=" + this.mag, 5.0f, 50.0f, Emulator.getDebugPaint());
        }
    }
