        public void handleMessage(Message msg) {
            if (msg.what == 4) {
                MAME4all.this.mHandler.sendEmptyMessageDelayed(4, 200000L);
            }
            if (msg.what == 2) {
                MAME4all.this.mHandler.removeMessages(2);
                Emulator.setPadData1(0, 512L);
                MAME4all.this.Sleep(100);
                Emulator.setPadData1(0, 0L);
                MAME4all.this.Sleep(100);
                Emulator.setPadData1(0, 256L);
                MAME4all.this.Sleep(100);
                Emulator.setPadData1(0, 0L);
                MAME4all.this.mHandler.sendEmptyMessageDelayed(2, 5000L);
                return;
            }
            if (msg.what == 1) {
                MAME4all.this.mHandler.removeMessages(1);
                if (!Emulator.isInMAME()) {
                    Emulator.setPadData1(0, 8192L);
                    MAME4all.this.Sleep(100);
                    Emulator.setPadData1(0, 0L);
                    MAME4all.this.mHandler.sendEmptyMessageDelayed(1, 300L);
                    MAME4all.this.bIsFinish = false;
                    return;
                }
                if (!MAME4all.this.bIsFinish) {
                    MAME4all.this.mlstCon.add(Integer.valueOf(IController.SELECT_VALUE));
                    MAME4all.this.mlstCon.add(Integer.valueOf(IController.START_VALUE));
                    MAME4all.this.mHandler.sendEmptyMessageDelayed(1, 10000L);
                    MAME4all.this.bIsFinish = true;
                    return;
                }
                if (MAME4all.this.gameView != null && MAME4all.this.gameView.getVisibility() != 0) {
                    MAME4all.this.gameView.setVisibility(0);
                }
                if (MAME4all.this.mProgressView != null && MAME4all.this.mProgressView.getVisibility() == 0) {
                    MAME4all.this.mProgressView.setVisibility(8);
                }
                if (MAME4all.this.mlstCon.size() > 0) {
                    int cmd = MAME4all.this.mlstCon.remove(0).intValue();
                    Emulator.setPadData1(0, cmd);
                    MAME4all.this.Sleep(100);
                    Emulator.setPadData1(0, 0L);
                    Log.v("", "isEmulating:" + Emulator.isEmulating());
                    Log.v("", "isInMAME:" + Emulator.isInMAME());
                }
                if (MAME4all.this.mlstCon.size() > 0) {
                    MAME4all.this.mHandler.sendEmptyMessageDelayed(1, 1000L);
                    return;
                }
