package com.seleuco.mame4all;

    public void run() {
        while (this.run) {
            try {
                synchronized (this) {
                    try {
                        if (this.run) {
                            wait();
                            if (!this.run) {
                                return;
                            }
                        } else {
                            return;
                        }
                    } catch (InterruptedException e) {
                        e.printStackTrace();
                    }
                }
                ByteBuffer bf = Emulator.getScreenBuffer();
                Bitmap bmp = Emulator.getEmuBitmap();
                if (bf != null && bmp != null) {
                    if (Emulator.getVideoRenderMode() == 4) {
                        bf.rewind();
                        bmp.copyPixelsFromBuffer(bf);
                        bmp.getPixels(Emulator.getScreenBuffPx(), 0, Emulator.getEmulatedWidth(), 0, 0, Emulator.getEmulatedWidth(), Emulator.getEmulatedHeight());
                        this.mm.getEmuView().postInvalidate();
                    } else {
                        this.canvas = Emulator.lockCanvas();
                        if (this.canvas != null) {
                            bf.rewind();
                            bmp.copyPixelsFromBuffer(bf);
                            this.i++;
                            this.canvas.concat(Emulator.getMatrix());
                            this.canvas.drawBitmap(bmp, 0.0f, 0.0f, Emulator.getEmuPaint());
                            if (Emulator.isDebug()) {
                                this.canvas.drawText("Threaded fps:" + this.fps + " w:" + Emulator.getWindow_width() + " h:" + Emulator.getWindow_height(), 5.0f, 40.0f, Emulator.getDebugPaint());
                                if (System.currentTimeMillis() - this.millis >= 1000) {
                                    this.fps = this.i;
                                    this.i = 0;
                                    this.millis = System.currentTimeMillis();
                                }
                            }
                            Emulator.unlockCanvas(this.canvas);
                        }
                    }
                }
            } catch (Exception t) {
                Log.getStackTraceString(t);
            }
        }
    }

