            super.onMeasure(widthMeasureSpec, heightMeasureSpec);
            return;
        }
        if (this.mm.getMainHelper().getscrOrientation() == 2) {
            widthSize = this.mm.getWindowManager().getDefaultDisplay().getWidth();
            heightSize = this.mm.getWindowManager().getDefaultDisplay().getHeight();
        } else {
            int w = 1;
            int h = 1;
            if (this.mm != null && this.mm.getInputHandler().getMainRect() != null) {
                w = this.mm.getInputHandler().getMainRect().width();
                h = this.mm.getInputHandler().getMainRect().height();
            }
            if (w == 0) {
                w = 1;
            }
            if (h == 0) {
                h = 1;
            }
            float desiredAspect = w / h;
            widthSize = this.mm.getWindowManager().getDefaultDisplay().getWidth();
            heightSize = (int) (widthSize / desiredAspect);
        }
        setMeasuredDimension(widthSize, heightSize);
